class Solution {
public:
    int divide(int dividend, int divisor) {
           // frsit case is to handle the overflow cases 
        // INT_MIN = -2147483648  and -2147483648 / -1 = 2147483648 it is bigger than INT_MAX
        if (dividend == INT_MIN && divisor == -1) {
            return INT_MAX;
        }


        //we must know the basic things that 
        //abs is used for interger 
        //labs is used for double 
        //llabs is used for long long 
        //llabs means that long long abstarct vlaue 

         // convert the postive numbers 
        long long number = llabs((long long) dividend);
        long long div = llabs((long long) divisor);

        // intalize the answer to store
        long long ans = 0;

        // now start looping As long as dividend is bigger than divisor, continue division.
        while (number >= div) {

            // inatlzie count 
            long long count = 0;

            // div << k  = div × 2^k
            // it meaans that 
            // 3 × 2^0 = 3
            // 3 × 2^1 = 6
            // 3 × 2^2 = 12
            // 3 × 2^3 = 24
            // 3 × 2^4 = 48  not possible
            while (number >= (div << (count + 1))) {
                count++;
            }

            // Add to the answer
            // 1 << 3 = 8 it means 2^3
            // 1 << 1 it means 2^1
            // 1 << 0 it means 2^0
            ans += (1LL << count);

            // finally we will subtract from number
            number -= (div << count);
        }

        // Apply for sign 
        // if xor is negtive then answer is also negative
        if ((dividend < 0) ^ (divisor < 0))
            ans = -ans;

        // finally return aswer
        return (int)ans;
    }
};
